// Adapted from shadcn/ui (MIT). See SHADCN-LICENSE.txt and upstream provenance.
"use client";

import * as React from "react";
import { cn } from "./utils";
import { Checkbox as CheckboxPrimitive } from "radix-ui";

function Checkbox({
  className,
  ...props
}: React.ComponentProps<typeof CheckboxPrimitive.Root>) {
  return (
    <CheckboxPrimitive.Root
      data-slot="checkbox"
      className={cn("roc-ui", className)}
      {...props}
    >
      <CheckboxPrimitive.Indicator
        data-slot="checkbox-indicator"
        className="roc-ui"
        forceMount
      >
        <svg
          className="roc-ui-icon roc-ui-checkbox-mark"
          viewBox="0 0 16 16"
          fill="none"
          stroke="currentColor"
          strokeWidth="2"
          strokeLinecap="round"
          strokeLinejoin="round"
          aria-hidden="true"
        >
          <path d="M3.5 8.5 6.5 11.5 12.5 4.5" pathLength={1} />
        </svg>
      </CheckboxPrimitive.Indicator>
    </CheckboxPrimitive.Root>
  );
}

export { Checkbox };

import "./checkbox.css";

import { clsx, type ClassValue } from "clsx";
/** Scoped CSS needs no Tailwind runtime or host configuration. */
export function cn(...inputs: ClassValue[]) {
  return clsx(inputs);
}

@import "./ui-base.css";
.roc-ui[data-slot="checkbox"] {
  display: inline-grid;
  place-items: center;
  position: relative;
  width: 20px;
  height: 20px;
  padding: 0;
  flex-shrink: 0;
  border: 1px solid var(--roc-line, #c7c7c7);
  border-radius: 5px;
  background: var(--roc-paper, #fff);
  cursor: pointer;
  transition:
    background-color var(--roc-motion-quick) var(--roc-motion-ease),
    border-color var(--roc-motion-quick) var(--roc-motion-ease);
}
.roc-ui[data-slot="checkbox"]::before {
  content: "";
  position: absolute;
  inset: -8px;
}
.roc-ui[data-slot="checkbox"][data-state="checked"],
.roc-ui[data-slot="checkbox"][data-state="indeterminate"] {
  background: var(--roc-ink, #252525);
  border-color: transparent;
  color: white;
}
.roc-ui[data-slot="checkbox-indicator"] {
  display: grid;
  place-items: center;
  color: inherit;
}
.roc-ui[data-slot="checkbox"][data-state="indeterminate"] svg {
  visibility: hidden;
}
.roc-ui[data-slot="checkbox"][data-state="indeterminate"]::after {
  content: "";
  position: absolute;
  width: 10px;
  height: 2px;
  background: currentColor;
}
/* The box fills first, then the mark draws itself. Unchecking retracts quickly. */
.roc-ui-checkbox-mark path {
  stroke-dasharray: 1 1;
  stroke-dashoffset: 1;
  opacity: 0;
  transition:
    stroke-dashoffset var(--roc-motion-quick) var(--roc-motion-ease),
    opacity 0s linear var(--roc-motion-quick);
}
.roc-ui[data-slot="checkbox"][data-state="checked"] .roc-ui-checkbox-mark path {
  stroke-dashoffset: 0;
  opacity: 1;
  transition:
    stroke-dashoffset var(--roc-motion-medium) var(--roc-motion-ease),
    opacity 0s;
}
@media (prefers-reduced-motion: reduce) {
  .roc-ui-checkbox-mark path {
    transition: none !important;
  }
}

/* Shared ROC foundations. No global reset or host stylesheet required. */
.roc-ui {
  box-sizing: border-box;
  font: inherit;
  font-size: 13px;
  color: var(--roc-ink, #252525);
}
.roc-ui *,
.roc-ui *::before,
.roc-ui *::after {
  box-sizing: border-box;
}
.roc-ui:focus-visible {
  outline: 2px solid var(--roc-focus, #737373);
  outline-offset: 3px;
}
.roc-ui:disabled,
.roc-ui[data-disabled] {
  opacity: 0.45;
  cursor: not-allowed;
}
/* Micro-motion scale, adapted from transitions.dev. Override on `.roc-ui`. */
:where(.roc-ui) {
  --roc-motion-quick: 150ms;
  --roc-motion-fast: 250ms;
  --roc-motion-medium: 350ms;
  --roc-motion-ease: cubic-bezier(0.22, 1, 0.36, 1);
  --roc-motion-bounce: cubic-bezier(0.34, 1.36, 0.64, 1);
  --roc-motion-blur: 2px;
}
.roc-ui-icon,
.roc-ui > svg {
  width: 16px;
  height: 16px;
  flex-shrink: 0;
  pointer-events: none;
}
.roc-ui-sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}
/* Surfaces scale in from their anchor and settle back more quietly on exit. */
@keyframes roc-ui-pop-in {
  from {
    opacity: 0;
    transform: scale(var(--roc-pop-scale, 0.97));
  }
}
@keyframes roc-ui-pop-out {
  to {
    opacity: 0;
    transform: scale(var(--roc-pop-scale-out, 0.99));
  }
}
/* Invalid fields answer with one short horizontal shake. */
@keyframes roc-ui-shake {
  20% {
    translate: 6px 0;
  }
  50% {
    translate: -6px 0;
  }
  78% {
    translate: 4px 0;
  }
}
@keyframes roc-ui-dismiss {
  from {
    opacity: 1;
  }
  to {
    opacity: 0;
  }
}
@media (prefers-reduced-motion: reduce) {
  .roc-ui,
  .roc-ui::before,
  .roc-ui::after {
    transition-duration: 0s !important;
    animation-duration: 0.01ms !important;
  }
}
